CREATE TABLE `marine-cycle-484213-b4.google_ads.p_ads_BudgetStats_4435779462`
(
  campaign_budget_id INT64 OPTIONS(description="The ID of the campaign budget. A campaign budget is created using the CampaignBudgetService create operation and is assigned a budget ID. A budget ID can be shared across different campaigns; the system will then allocate the campaign budget among different campaigns to get optimum results."),
  campaign_id INT64 OPTIONS(description="The ID of the campaign."),
  customer_id INT64 OPTIONS(description="The ID of the customer."),
  campaign_budget_recommended_budget_estimated_change_weekly_clicks INT64 OPTIONS(description="The estimated change in weekly clicks if the recommended budget is applied. This field is read-only."),
  campaign_budget_recommended_budget_estimated_change_weekly_cost_micros INT64 OPTIONS(description="The estimated change in weekly cost in micros if the recommended budget is applied. One million is equivalent to one currency unit. This field is read-only."),
  campaign_budget_recommended_budget_estimated_change_weekly_interactions INT64 OPTIONS(description="The estimated change in weekly interactions if the recommended budget is applied. This field is read-only."),
  campaign_budget_recommended_budget_estimated_change_weekly_views INT64 OPTIONS(description="The estimated change in weekly views if the recommended budget is applied. This field is read-only."),
  campaign_name STRING OPTIONS(description="The name of the campaign. This field is required and should not be empty when creating new campaigns. It must not contain any null (code point 0x0), NL line feed (code point 0xA) or carriage return (code point 0xD) characters."),
  campaign_status STRING OPTIONS(description="The status of the campaign. When a new campaign is added, the status defaults to ENABLED."),
  metrics_all_conversions FLOAT64 OPTIONS(description="The total number of conversions. This only includes conversion actions which include_in_conversions_metric attribute is set to true."),
  metrics_all_conversions_from_interactions_rate FLOAT64 OPTIONS(description="All conversions from interactions (as oppose to view through conversions) divided by the number of ad interactions."),
  metrics_all_conversions_value FLOAT64 OPTIONS(description="The total value of all conversions."),
  metrics_average_cost FLOAT64 OPTIONS(description="The average amount you pay per interaction. This amount is the total cost of your ads divided by the total number of interactions."),
  metrics_average_cpc FLOAT64 OPTIONS(description="The total cost of all clicks divided by the total number of clicks received."),
  metrics_average_cpe FLOAT64 OPTIONS(description="The average amount that you've been charged for an ad engagement. This amount is the total cost of all ad engagements divided by the total number of ad engagements."),
  metrics_average_cpm FLOAT64 OPTIONS(description="Average cost-per-thousand impressions (CPM)."),
  metrics_clicks INT64 OPTIONS(description="The number of clicks."),
  metrics_conversions FLOAT64 OPTIONS(description="The number of conversions. This only includes conversion actions which include_in_conversions_metric attribute is set to true."),
  metrics_conversions_from_interactions_rate FLOAT64 OPTIONS(description="Conversions from interactions divided by the number of ad interactions (such as clicks for text ads or views for video ads). This only includes conversion actions which include_in_conversions_metric attribute is set to true."),
  metrics_conversions_value FLOAT64 OPTIONS(description="The total value of conversions. This only includes conversion actions which include_in_conversions_metric attribute is set to true."),
  metrics_cost_micros INT64 OPTIONS(description="The sum of your cost-per-click (CPC) and cost-per-thousand impressions (CPM) costs during this period."),
  metrics_cost_per_all_conversions FLOAT64 OPTIONS(description="The cost of ad interactions divided by all conversions."),
  metrics_cost_per_conversion FLOAT64 OPTIONS(description="The cost of ad interactions divided by conversions. This only includes conversion actions which include_in_conversions_metric attribute is set to true."),
  metrics_cross_device_conversions FLOAT64 OPTIONS(description="Conversions from when a customer clicks on a Google Ads ad on one device, then converts on a different device or browser. Cross-device conversions are already included in all_conversions."),
  metrics_ctr FLOAT64 OPTIONS(description="The number of clicks your ad receives (Clicks) divided by the number of times your ad is shown (Impressions)."),
  metrics_engagement_rate FLOAT64 OPTIONS(description="How often people engage with your ad after it's shown to them. This is the number of ad expansions divided by the number of times your ad is shown."),
  metrics_engagements INT64 OPTIONS(description="The number of engagements. An engagement occurs when a viewer expands your Lightbox ad. Also, in the future, other ad types may support engagement metrics."),
  metrics_impressions INT64 OPTIONS(description="Count of how often your ad has appeared on a search results page or website on the Google Network."),
  metrics_interaction_event_types STRING OPTIONS(description="The types of payable and free interactions."),
  metrics_interaction_rate FLOAT64 OPTIONS(description="How often people interact with your ad after it is shown to them. This is the number of interactions divided by the number of times your ad is shown."),
  metrics_interactions INT64 OPTIONS(description="The number of interactions. An interaction is the main user action associated with an ad format-clicks for text and shopping ads, views for video ads, and so on."),
  metrics_trueview_average_cpv FLOAT64 OPTIONS(description="The average amount you pay each time someone views your ad. The average CPV is defined by the total cost of all ad views divided by the number of TrueView views."),
  metrics_value_per_all_conversions FLOAT64 OPTIONS(description="The value of all conversions divided by the number of all conversions."),
  metrics_value_per_conversion FLOAT64 OPTIONS(description="The value of conversions divided by the number of conversions. This only includes conversion actions which include_in_conversions_metric attribute is set to true."),
  metrics_video_trueview_view_rate FLOAT64 OPTIONS(description="The number of TrueView views your video ad receives divided by its number of impressions, including thumbnail impressions for TrueView in-display ads."),
  metrics_video_trueview_views INT64 OPTIONS(description="The number of TrueView views your video ads received."),
  metrics_view_through_conversions INT64 OPTIONS(description="The total number of view-through conversions. These happen when a customer sees an image or rich media ad, then later completes a conversion on your site without interacting with (e.g., clicking on) another ad."),
  segments_date DATE OPTIONS(description="Date to which metrics apply. yyyy-MM-dd format, e.g., 2018-04-17.")
)
PARTITION BY DATE(_PARTITIONTIME);
